package com.treepeople.leapmindtts.service.profile.platform;
import java.math.BigDecimal; import java.time.Instant; import java.util.List;
public record LessonPrepProfileContext(Long userId, String sceneType, ProfileContextStatus profileStatus, String statusReason, Long profileVersion, Instant computedAt, Instant lastUpdated, BigDecimal confidence, ProfileAvailability availability, List<ProfileKnowledgeContext> weakKnowledgePoints, String grade, List<String> preferredContentModes, String learningPace, List<String> teachingSuggestions, String summaryText) {
    public LessonPrepProfileContext { boolean facts = !ProfileContextFields.list(weakKnowledgePoints).isEmpty() || grade != null || !ProfileContextFields.list(preferredContentModes).isEmpty() || learningPace != null || !ProfileContextFields.list(teachingSuggestions).isEmpty() || summaryText != null; ProfileContextFields.envelope(userId, sceneType, "lesson_prep", profileStatus, statusReason, profileVersion, computedAt, lastUpdated, confidence, availability, facts); weakKnowledgePoints = ProfileContextFields.list(weakKnowledgePoints, 100, "weakKnowledgePoints"); preferredContentModes = ProfileContextFields.contentModes(preferredContentModes); learningPace = ProfileContextFields.pace(learningPace); teachingSuggestions = ProfileContextFields.suggestions(teachingSuggestions); summaryText = ProfileContextFields.summary(summaryText); }
}
